-- Confirmed policy: regulars receive physical shuttles; paid spares receive $20.
-- This changes terms for future publication only; signed versions and receipts stay immutable.
begin;
create or replace function club_app.agreement_terms() returns text language sql immutable set search_path='' as $$ select E'Organizer: Christy, acting personally. Maplewood Advanced Badminton League is the league name, not a separately registered club.\nRegular season fee: $400; approved spare session: $20. A payment claim is not proof of payment. Spare places are confirmed only after voting, verified payment and availability.\nEligible absence refund: $14 for notice received at least 72 elapsed hours before the session starts. Late notice and no-shows are not eligible.\nSchool/facility cancellations: affected eligible regular players receive two physical shuttlecocks with no cash refund. Confirmed paid spares receive a full $20 refund.\nVerified no-show: one court down, with administrator review and correction. No response alone is not proof of a no-show.\nChristy sets initial seeding. Ratings and court movement follow published rules; administrators may make audited corrections.\nBookings 20:15–22:15 Toronto time: no early entry, finish play by 22:05 and leave by 22:15. Indoor non-marking shoes and school facility conditions apply.\nThere is no minimum participant age. All players under 18 require verified parent/legal-guardian consent. Adult participants sign for themselves.\nRegistration and acceptance are season-specific. A new season requires its own signed agreement; earlier receipts remain on record.\n' $$;
notify pgrst, 'reload schema';
commit;
